    passage:
      '働く人の間で、睡眠時間を削って働く姿勢を「意欲が高い」と評価する風潮が根強い。会議の最初に眠気を隠す同僚、深夜のメールの送信時刻を自慢する上司。だが、睡眠研究の知見が積み上がるにつれ、こうした自己犠牲の実態が見えてきた。眠れない夜を重ねた人の判断は、酔った人の判断に近づくという報告がある。注意力の低下、感情の制御の甘さ、記憶の定着の不調。つまり睡眠時間の削減は、働く時間の延長ではなく、働く能力の目減りと引き換えになっている。\n皮肉なことに、疲労を押して生み出された仕事は、翌日のやり直しを要求することが多い。徹夜で作った資料が、翌朝の自分には読めず、結局作り直す。そうした「二度手間」を集計すれば、削った睡眠は思ったほど生産性に回っていないはずだ。\n⟪睡眠は仕事から奪うものではなく、仕事の土台を支える設備なのだ⟫。設備投資を惜しんだ工場が故障を重ねるように、睡眠を削った頭は、同じ仕事に倍の時間をかける。だからこそ、睡眠時間を削って働くことを「頑張り」と呼び、削らないことを「手を抜き」と呼ぶ評価の仕方こそ、見直されるべきなのである。',
