    id: 'sim-chu12', typeKey: 'chubun', title: '模拟㊻ 動物園という世界', minutes: 5,
    source: '本站原创模拟（非真题）',
    passage:
      '動物園への批判は、かつて「檻の中の動物はかわいそう」という形だった。それならと、各国の動物園は飼育環境の改良を進めた。広い放飼場、隠れ家、遊びの仕掛け。檻という言葉自体が使われなくなった。しかし改良された環境を見た観客の間で、今度は別の問いが立ち上がった。そもそも、なぜ動物を都市の中で飼うのか。\n動物園側の答えは、二つに整理できる。一つは種の保存だ。絶滅の危機にある種を、園内で繁殖させる。もう一つは教育だ。実物の動物に接した感動は、図鑑では代えがたい。どちらも筋は通っている。ただ、繁殖の話には一つ、難しい注がつく。園内で生まれ育った個体は、野生に戻すのが極めて難しい。保護の名の下に生まれた子は、そのまま園で一生を終える。つまり、⟪動物園は、未来への避難所であると同時に、生まれた子にとっては世界そのものになってしまう⟫。この注を正面から受け止めるとき、動物園の責任は「環境を良くすること」から、「どんな一生を与えるか」へと移る。',
